async function releaseForecast(){if(!editor.value?.name||editor.value.doctype!=='Harvest Forecast'||editor.value.supply_state!=='Draft'||!session.commands.forecast_release)return;dialogBusy.value=true;await run(async()=>{const d=editor.value;const values={...cleanFields(schema.value,d),supply_state:'Released'};editor.value=await consoleAPI('save',{doctype:d.doctype,name:d.name,base_modified:d.modified,values},true);message.value='Đã phát hành dự thu. Hệ thống đã khóa số liệu nguồn.';await load()});dialogBusy.value=false}
