async function ingestScale(){if(!scope.farm){error.value='Chọn vườn trước.';return}if(!scaleInput.reading_id)scaleInput.reading_id=crypto.randomUUID();if(!scaleInput.captured_at)scaleInput.captured_at=new Date().toISOString();await command('lotus_farm.api.ingest_scale',{farm:scope.farm,device_id:scaleInput.device_id,reading_id:scaleInput.reading_id,captured_at:scaleInput.captured_at,gross_kg:scaleInput.gross_kg,tare_kg:scaleInput.tare_kg})}
async function downloadDataset(){const result=await run(()=>call('lotus_farm.reporting.dataset',{from_date:scope.from_date||scope.date,to_date:scope.to_date||scope.date,farm:scope.farm||null,company:scope.company||null,block:scope.block||null,plot:scope.plot||null,cycle:scope.cycle||null}));if(!result)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`lotus-dataset-${scope.farm||'all'}-${scope.from_date||scope.date}-${scope.to_date||scope.date}.json`;a.click();URL.revokeObjectURL(url)}
